// The touch-button art: the user's neon ring picture (green / pink / lilac rings in a purple cog), cut out and scaled to the overlay's pixel grid, embedded as a data URI.
// One 64 x 42 sheet: a 42 x 42 face for the four big buttons (steer left / right, jump, slide) at (0, 0) and a 22 x 22 face for the pause button at (42, 0). Made by tools/make_touch_assets.py.
// hi = the same picture at 256 x 256 (WebP with alpha) for the SMOOTH layer (canvas #touch, drawn at the device's resolution, anti-aliased); the pixel sheet above is the fallback.
const TOUCH_ART = { src: 'data:image/png;base64,', big: { x: 0, y: 0, w: 42, h: 42 }, small: { x: 42, y: 0, w: 22, h: 22 }, hi: { src: 'data:image/webp;base64,', w: 256, h: 256 } };
